import glob, os, runpy, sys
def usable(p):
    return bool(p) and '${' not in p and os.path.isfile(os.path.join(p, 'sia_mcp.py'))
def version(p):
    try:
        return tuple(int(x) for x in os.path.basename(p.rstrip('/')).split('.'))
    except ValueError:
        return ()
candidates = sys.argv[1:] + [os.environ.get(k, '') for k in ('CLAUDE_PLUGIN_ROOT', 'PLUGIN_ROOT')]
candidates += sorted(glob.glob(os.path.expanduser('~/.codex/plugins/cache/*/sia/*')), key=version, reverse=True)
root = next((p for p in candidates if usable(p)), None)
if root is None:
    sys.exit('sia: cannot locate the plugin root; no host-provided path and no Codex cache install found')
runpy.run_path(os.path.join(root, 'sia_mcp.py'), run_name='__main__')
